import React, { useEffect } from 'react';

const MinimalPortfolio = () => {
  useEffect(() => {
    document.title = 'Ranvir Deshmukh - Minimal Portfolio';
  }, []);

  return (
    <div style={styles.container}>
      {/* Name / Title */}
      <h1 style={styles.name}>Ranvir Deshmukh</h1>

      {/* Short Tagline */}
      <h2 style={styles.tagline}>Founder, Software Engineer, ML Researcher, Video Producer</h2>

      {/* Brief Bio / Description */}
      <p style={styles.description}>
        I’m currently building [Your Current Project]. <br />
        Previously founded [Any Previous Ventures] (maybe one acquired!). <br />
        Studying Computer Science and Economics at Dartmouth. <br />
        Reach out — I’m always open to chat!
      </p>

      {/* Links */}
      <div style={styles.linkContainer}>
        <a 
          href="https://www.linkedin.com/in/YOUR_LINKEDIN" 
          style={styles.linkStyle}
          target="_blank"
          rel="noopener noreferrer"
        >
          LinkedIn
        </a>
        <span style={styles.linkSeparator}>|</span>
        <a 
          href="https://github.com/YOUR_GITHUB" 
          style={styles.linkStyle}
          target="_blank"
          rel="noopener noreferrer"
        >
          GitHub
        </a>
      </div>
    </div>
  );
};

const styles = {
  container: {
    backgroundColor: '#FFFFFF',
    color: '#000000',
    minHeight: '100vh',
    fontFamily: "'Helvetica Neue', sans-serif",
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '0 20px',
  },
  name: {
    fontSize: '64px',
    margin: '0 0 10px 0',
    fontWeight: 700,
  },
  tagline: {
    fontSize: '20px',
    margin: '0 0 30px 0',
    fontWeight: 400,
    opacity: 0.8,
  },
  description: {
    fontSize: '16px',
    maxWidth: '600px',
    textAlign: 'center',
    lineHeight: '1.6',
    marginBottom: '30px',
  },
  linkContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
  },
  linkStyle: {
    textDecoration: 'none',
    color: '#000000',
    fontWeight: 500,
  },
  linkSeparator: {
    color: '#000000',
    opacity: 0.6,
  },
};

export default MinimalPortfolio;
